mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM dms_shop_order_item
WHERE order_id = #{orderId}

SELECT COALESCE(SUM(item.quantity), 0)
FROM dms_shop_order_item item
INNER JOIN dms_shop_order order_header ON order_header.id = item.order_id
WHERE order_header.user_id = #{userId}
  AND order_header.tenant_id = #{tenantId}
  AND item.product_id = #{productId}
  AND order_header.status IN (0, 1, 2, 3)
